#include "robotblocks_runtime.h"
#include <Servo.h>

inline void servos_mover(Servo& servo, int pin, float angulo, const char* bloque);
inline void servos_mover(Servo& servo, int pin, float angulo, const char* bloque) {
    if (!servo.attached()) servo.attach(pin, 500, 2500);
    if (!servo.attached()) { rb_fail(bloque, RB_ERROR_TEXT("No se pudo activar Servo.h")); return; }
    angulo = fmaxf(0, fminf(180, rb_finite(angulo, bloque)));
    servo.writeMicroseconds(int(500 + angulo * 2000 / 180));
}
static Servo servo_9;

static void proceso_1() {
    static RbProcessState s;
    float rb_t1;
    float rb_t2;
    float rb_t3;
    PT_BEGIN(s);
    while (true) {
        rb_t1 = analogRead(A0);
        rb_t2 = rb_map(rb_t1, 0, 1023, 0, 180, "aprende-461");
        if (rb_failed) return;
        rb_t3 = rb_clamp(rb_t2, 0, 180, "aprende-464");
        if (rb_failed) return;
        servos_mover(servo_9, 9, rb_t3, "aprende-465");
        if (rb_failed) return;
        PT_SLEEP(s, 100);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); }

void loop() { rb_error_repeat(); proceso_1(); }
